// features/vendor-lifecycle.feature: "A certificate whose expiry date could not be read cannot be approved"
import { expect, expectStatus, test } from "../../fixtures";

test("a certificate whose expiry date could not be read cannot be approved", { tag: "@LIF-08" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review whose insurance certificate has the expiry date "next spring"
  const { documents, extractions } = await factory.vendorInReview({
    files: { insurance_certificate: "insurance_certificate_unparseable.txt" },
  });
  const certificate = extractions.insurance_certificate;
  const reviewer = await apiAs("reviewer");

  // Act: the reviewer approves the insurance certificate extraction
  const response = await reviewer.post(`/api/extractions/${certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: the approval is refused with the expiry-missing error
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expiry_missing");

  // Assert: the stored extraction is still awaiting review
  const stored = await factory.extraction(documents.insurance_certificate.id, "reviewer");
  expect(stored.status).toBe("pending_review");
});
